async function createProRoom(){const btn=$('#proCreateRoomBtn');busy(btn,true,'Criando sala…');status('#proCreateRoomStatus','Criando sala, aplicando dinâmica e regras…','busy');try{const bridge=window.quiz2AdminBridge;if(!bridge?.createGameShowRoom)throw new Error('O controlador principal do ADM ainda não está pronto. Recarregue a página.');const mode=document.querySelector('[name="proGameMode"]:checked')?.value||proDraftMode||'classic';if(mode==='teams'&&proBackendSchema<TEAM_FEATURE_SCHEMA_REQUIRED)throw new Error('Para Equipes com Automático/Jogador/ADM, execute 00_ATUALIZAR_SUPABASE_PARA_SCHEMA_043.sql. Os demais modos GameShow já funcionam no schema 042.');const title=$('#proRoomTitle').value.trim()||'Quiz GameShow Pro',plannedRounds=Math.max(1,Math.min(200,Number($('#proPlannedRounds').value)||10)),settingsPatch={...modePresets[mode],...quickRulesPatch(),game_mode:mode,team_join_mode:mode==='teams'?selectedTeamJoinMode():'auto'};let teams=mode==='teams'?teamsFromUi():[];if(mode==='teams'&&teams.length<2)teams=generateDefaultTeams(Number($('#proTeamCount')?.value)||4);const created=await bridge.createGameShowRoom({title,plannedRounds,settingsPatch,teams});if(!created)throw new Error('A criação da sala foi cancelada ou não concluída.');proRoom=created;proDraftMode=mode;await refreshPro();status('#proCreateRoomStatus',`✓ Sala ${proRoom.code} criada. Agora escolha as perguntas.`,'ok');setProPane('questions');}catch(e){status('#proCreateRoomStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
