function selectedTeamJoinMode(){return document.querySelector('[name="proTeamJoinMode"]:checked')?.value||proDraftTeamJoinMode||'auto';}
function teamJoinModeLabel(mode){return({auto:'Automático equilibrado',player:'Jogador escolhe',admin:'ADM escolhe'})[mode]||'Automático equilibrado';}
function setTeamFormationUi(mode){const safe=['auto','player','admin'].includes(mode)?mode:'auto';proDraftTeamJoinMode=safe;$$('[name="proTeamJoinMode"]').forEach(r=>{r.checked=r.value===safe;r.closest('.pro-team-formation-option')?.classList.toggle('active',r.checked);});const badge=$('#proTeamFormationBadge');if(badge)badge.textContent=safe==='auto'?'AUTOMÁTICO':safe==='player'?'JOGADOR':'ADM';const msg=safe==='auto'?'O sistema distribui os jogadores equilibrando a quantidade por time.':safe==='player'?'O jogador escolherá a equipe no celular depois de entrar com nome e avatar.':'Os jogadores entram sem equipe; distribua no painel do lobby por seletor ou arrastando.';status('#proTeamFormationStatus',msg,'ok');const board=$('#proTeamAdminBoard');if(board)board.dataset.joinMode=safe;const title=$('#proTeamAdminTitle'),hint=$('#proTeamAdminHint');if(title)title.textContent=safe==='admin'?'Distribuição pelo ADM':safe==='player'?'Acompanhar escolhas dos jogadores':'Distribuição automática';if(hint)hint.textContent=safe==='admin'?'Arraste jogadores entre as colunas ou use o seletor em cada jogador.':safe==='player'?'Acompanhe em tempo real qual equipe cada jogador escolheu.':'O sistema coloca novos jogadores na equipe com menos pessoas.';}
function syncTeamFormationFromRoom(){const mode=proRoom?(settings().team_join_mode||'auto'):proDraftTeamJoinMode;setTeamFormationUi(mode);}
async function changeTeamJoinMode(mode){if(proBackendSchema<TEAM_FEATURE_SCHEMA_REQUIRED){status('#proTeamFormationStatus','Os 3 modos de formação de equipes exigem schema 043. Execute 00_ATUALIZAR_SUPABASE_PARA_SCHEMA_043.sql.','error');return;}setTeamFormationUi(mode);if(!proRoom){status('#proTeamFormationStatus',`${teamJoinModeLabel(mode)} será aplicado quando a sala for criada.`,'ok');return;}if((settings().game_mode||proDraftMode)!=='teams'){status('#proTeamFormationStatus','Selecione a dinâmica Equipes para configurar a formação.','error');return;}status('#proTeamFormationStatus','Salvando forma de montar as equipes…','busy');try{const{data,error}=await db.rpc('admin_set_team_join_mode',{p_room_id:proRoom.id,p_mode:mode});if(error)throw error;proRoom.settings={...settings(),team_join_mode:data?.team_join_mode||mode};setTeamFormationUi(proRoom.settings.team_join_mode);status('#proTeamFormationStatus',`✓ ${teamJoinModeLabel(proRoom.settings.team_join_mode)} salvo para esta sala.`,'ok');await loadTeamLobbyState();}catch(e){status('#proTeamFormationStatus',e.message||String(e),'error');syncTeamFormationFromRoom();}}
function teamSelectOptions(teams,current){return`<option value="">Sem equipe</option>${teams.map(t=>`<option value="${esc(t.id)}" ${String(current||'')===String(t.id)?'selected':''}>${esc(t.icon||'●')} ${esc(t.name)}</option>`).join('')}`;}
function renderTeamAssignmentBoard(){const box=$('#proTeamAssignmentBoard'),summary=$('#proTeamAssignmentSummary');if(!box||!summary)return;if(!proRoom){summary.textContent='Crie a sala para acompanhar os jogadores.';box.innerHTML='';return;}const state=proTeamLobbyState||{},teams=Array.isArray(state.teams)?state.teams:proTeams||[],players=Array.isArray(state.players)?state.players:[],mode=state.join_mode||selectedTeamJoinMode(),adminMode=mode==='admin';const assigned=players.filter(p=>p.team_id).length;summary.textContent=`${players.length} jogador${players.length===1?'':'es'} • ${assigned} com equipe • ${players.length-assigned} aguardando • ${teamJoinModeLabel(mode)}`;const cols=[{id:'',name:'Sem equipe',color:'#7b8da1',icon:'○'},...teams];box.innerHTML=cols.map(t=>{const rows=players.filter(p=>String(p.team_id||'')===String(t.id||''));return`<section class="pro-team-drop-column ${!t.id?'unassigned':''}" data-team-drop="${esc(t.id||'')}"><header><i style="background:${esc(t.color||'#7b8da1')}"></i><strong>${esc(t.icon||'○')} ${esc(t.name)}</strong><span>${rows.length}</span></header><div class="pro-team-drop-list">${rows.map(p=>`<article class="pro-team-player-chip ${p.connected?'online':'offline'}" draggable="${adminMode?'true':'false'}" data-participant-id="${esc(p.id)}"><div><span>${p.connected?'●':'○'}</span><strong>${esc(p.name||'Jogador')}</strong>${p.ready?'<small>PRONTO</small>':'<small>AGUARDANDO</small>'}</div><select aria-label="Equipe de ${esc(p.name||'jogador')}" data-team-player-select ${adminMode?'':'disabled'}>${teamSelectOptions(teams,p.team_id)}</select></article>`).join('')||'<div class="pro-team-drop-empty">Nenhum jogador</div>'}</div></section>`;}).join('');box.querySelectorAll('[data-team-player-select]').forEach(sel=>sel.addEventListener('change',e=>assignParticipantTeam(e.target.closest('[data-participant-id]')?.dataset.participantId,e.target.value||null)));if(adminMode){box.querySelectorAll('[data-participant-id]').forEach(chip=>chip.addEventListener('dragstart',e=>{e.dataTransfer?.setData('text/plain',chip.dataset.participantId||'');e.dataTransfer.effectAllowed='move';chip.classList.add('dragging');}));box.querySelectorAll('[data-participant-id]').forEach(chip=>chip.addEventListener('dragend',()=>chip.classList.remove('dragging')));box.querySelectorAll('[data-team-drop]').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over');});col.addEventListener('dragleave',()=>col.classList.remove('drag-over'));col.addEventListener('drop',e=>{e.preventDefault();col.classList.remove('drag-over');assignParticipantTeam(e.dataTransfer?.getData('text/plain')||'',col.dataset.teamDrop||null);});});}}
async function loadTeamLobbyState(){if(proBackendSchema<TEAM_FEATURE_SCHEMA_REQUIRED){proTeamLobbyState=null;renderTeamAssignmentBoard();return;}if(!proRoom||(settings().game_mode||proDraftMode)!=='teams'){proTeamLobbyState=null;renderTeamAssignmentBoard();return;}try{const{data,error}=await db.rpc('admin_team_lobby_state',{p_room_id:proRoom.id});if(error)throw error;proTeamLobbyState=data||null;if(data?.join_mode){proRoom.settings={...settings(),team_join_mode:data.join_mode};setTeamFormationUi(data.join_mode);}renderTeamAssignmentBoard();renderTeamPreview();}catch(e){status('#proTeamAssignmentStatus',e.message||String(e),'error');}}
async function assignParticipantTeam(participantId,teamId){if(teamAssignmentBusy||!participantId||!proRoom)return;if((proTeamLobbyState?.join_mode||selectedTeamJoinMode())!=='admin'){status('#proTeamAssignmentStatus','Troque a formação para “ADM escolhe” para mover jogadores manualmente.','error');return;}teamAssignmentBusy=true;status('#proTeamAssignmentStatus','Movendo jogador…','busy');try{const{data,error}=await db.rpc('admin_assign_participant_team',{p_room_id:proRoom.id,p_participant_id:participantId,p_team_id:teamId||null});if(error)throw error;proTeamLobbyState=data||proTeamLobbyState;renderTeamAssignmentBoard();status('#proTeamAssignmentStatus','✓ Equipe atualizada. O jogador deverá confirmar “Estou pronto” novamente.','ok');await loadTeamRank();}catch(e){status('#proTeamAssignmentStatus',e.message||String(e),'error');await loadTeamLobbyState();}finally{teamAssignmentBusy=false;}}

function teamRow(team={},i=0){const row=document.createElement('div');row.className='pro-team-row';const color=team.color||TEAM_COLORS[i%TEAM_COLORS.length],icon=team.icon||'★';row.innerHTML=`<span class="pro-team-icon" style="background:${esc(color)}">${esc(icon)}</span><input aria-label="Nome da equipe" data-team-name maxlength="40" value="${esc(team.name||`Equipe ${i+1}`)}"><input aria-label="Cor da equipe" data-team-color type="color" value="${esc(color)}"><button aria-label="Remover equipe" class="ghost danger-soft pro-team-remove" type="button">×</button>`;row.querySelector('[data-team-color]').addEventListener('input',e=>{row.querySelector('.pro-team-icon').style.background=e.target.value;renderTeamPreview();});row.querySelector('[data-team-name]').addEventListener('input',renderTeamPreview);row.querySelector('.pro-team-remove').addEventListener('click',()=>{row.remove();renderTeamPreview();});return row;}
function renderTeams(){const box=$('#proTeamList');if(!box)return;box.innerHTML='';(proTeams.length?proTeams:[{name:'Equipe Azul',color:'#1976d2',icon:'●'},{name:'Equipe Verde',color:'#20a06c',icon:'●'},{name:'Equipe Laranja',color:'#d94b62',icon:'●'},{name:'Equipe Amarela',color:'#dda029',icon:'●'}]).forEach((t,i)=>box.append(teamRow(t,i)));if($('#proTeamCount'))$('#proTeamCount').value=Math.max(2,box.children.length);queueMicrotask(renderTeamPreview);}
function teamsFromUi(){return[...$('#proTeamList').children].map((row,i)=>({name:row.querySelector('[data-team-name]')?.value.trim()||`Equipe ${i+1}`,color:row.querySelector('[data-team-color]')?.value||TEAM_COLORS[i%TEAM_COLORS.length],icon:row.querySelector('.pro-team-icon')?.textContent||'★'})).filter(x=>x.name).slice(0,12);}
async function loadTeams(){if(!proRoom){proTeams=[];proTeamLobbyState=null;renderTeams();renderTeamAssignmentBoard();return;}const{data,error}=await db.rpc('admin_list_teams',{p_room_id:proRoom.id});if(error)throw error;proTeams=Array.isArray(data)?data:[];renderTeams();await Promise.allSettled([loadTeamRank(),loadTeamLobbyState()]);}
async function saveTeams(){const btn=$('#proSaveTeamsBtn');if(proBackendSchema<TEAM_FEATURE_SCHEMA_REQUIRED){status('#proTeamsStatus','Atualize o Supabase para schema 043 antes de salvar equipes.','error');return;}busy(btn,true);status('#proTeamsStatus','Salvando equipes…','busy');try{if(!proRoom)throw new Error('Crie uma sala primeiro.');const rows=teamsFromUi();if(rows.length<2)throw new Error('Use pelo menos duas equipes.');const{data,error}=await db.rpc('admin_save_teams',{p_room_id:proRoom.id,p_teams:rows});if(error)throw error;proTeams=Array.isArray(data)?data:rows;renderTeams();status('#proTeamsStatus',`✓ ${proTeams.length} equipes salvas.`,'ok');await Promise.allSettled([loadTeamRank(),loadTeamLobbyState()]);renderTeamPreview();}catch(e){status('#proTeamsStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
async function loadTeamRank(){const box=$('#proTeamRank');if(!proRoom){box.innerHTML='';return;}const{data}=await db.rpc('pro_public_team_ranking',{p_code:proRoom.code});const rows=Array.isArray(data)?data:[];box.innerHTML=rows.map((r,i)=>`<div class="pro-team-rank-row"><b>${i+1}</b><i style="background:${esc(r.color||'#1976d2')}"></i><strong>${esc(r.name)}</strong><span>${Number(r.points)||0} pts</span><small>${Number(r.players)||0} jogadores</small></div>`).join('')||'<div class="pro-status">Sem pontuação por equipe ainda.</div>';}

async function loadQuestions(){const{data,error}=await db.rpc('admin_list_question_bank',{p_scope:'active'});if(error)throw error;proQuestions=Array.isArray(data)?data:[];const sel=$('#proQuestionSelect'),keep=sel.value;sel.innerHTML='<option value="">Selecione…</option>'+proQuestions.map(q=>`<option value="${esc(q.id)}">${q.starred?'★ ':''}${esc(String(q.prompt||'').slice(0,100))}</option>`).join('');if(proQuestions.some(q=>String(q.id)===keep))sel.value=keep;$('#proMediaCount').textContent=`${proQuestions.length} perguntas`;loadQuestionFields();}
function selectedQuestion(){return proQuestions.find(q=>String(q.id)===String($('#proQuestionSelect').value))||null;}
function loadQuestionFields(){const q=selectedQuestion();$('#proMediaType').value=q?.media_type||'none';$('#proMediaUrl').value=q?.media_url||'';$('#proMediaCaption').value=q?.media_caption||'';$('#proSpecialType').value=q?.special_type||'normal';$('#proQuestionTags').value=Array.isArray(q?.tags)?q.tags.join(', '):'';$('#proQuestionSource').value=q?.source_label||'';$('#proQuestionStarred').checked=!!q?.starred;loadGameFields(q);renderMediaPreview();}
function renderMediaPreview(){const box=$('#proMediaPreview'),type=$('#proMediaType').value,url=safeUrl($('#proMediaUrl').value),cap=$('#proMediaCaption').value.trim();if(type==='none'){box.innerHTML='<span>Sem mídia nesta pergunta.</span>';return;}if(!url){box.innerHTML='<span>Informe uma URL HTTPS válida para visualizar.</span>';return;}if(type==='image')box.innerHTML=`<img alt="${esc(cap||'Prévia da pergunta')}" src="${esc(url)}">`;
else if(type==='audio')box.innerHTML=`<audio controls preload="metadata" src="${esc(url)}"></audio>`;
else box.innerHTML=`<video controls muted preload="metadata" src="${esc(url)}"></video>`;}
async function saveQuestionPro(){const btn=$('#proSaveQuestionBtn');busy(btn,true);status('#proQuestionStatus','Salvando…','busy');try{const q=selectedQuestion();if(!q)throw new Error('Selecione uma pergunta.');const type=$('#proMediaType').value,url=$('#proMediaUrl').value.trim();if(type!=='none'&&!safeUrl(url))throw new Error('Use uma URL HTTPS válida.');const tags=$('#proQuestionTags').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,20);const media=await db.rpc('admin_update_question_pro',{p_question_id:q.id,p_media_type:type,p_media_url:url,p_media_caption:$('#proMediaCaption').value.trim(),p_special_type:$('#proSpecialType').value,p_tags:tags,p_source_label:$('#proQuestionSource').value.trim(),p_starred:$('#proQuestionStarred').checked});if(media.error)throw media.error;const gameType=$('#proGameType').value||'standard',gameSpec=gameSpecFromUi(q,gameType);const game=await db.rpc('admin_update_question_game',{p_question_id:q.id,p_game_type:gameType,p_game_spec:gameSpec});if(game.error)throw game.error;status('#proQuestionStatus',`✓ Mídia + ${GAME_LABELS[gameType]||gameType} salvos.`,'ok');status('#proGameSpecStatus','Configuração congelada na próxima vez que a pergunta entrar na fila.','ok');await loadQuestions();}catch(e){status('#proQuestionStatus',e.message||String(e),'error');}finally{busy(btn,false);}}

function refreshBrandPreview(){const title=proRoom?.title||'Seu evento',sub=$('#proBrandSubtitle')?.value.trim()||'Subtítulo do evento',sponsor=$('#proSponsorName')?.value.trim()||'QUIZ ROUNDS 2';$('#proBrandPreviewTitle').textContent=title;$('#proBrandPreviewSubtitle').textContent=sub;$('#proBrandPreviewSponsor').textContent=sponsor;}
async function saveProSettings(){const btn=$('#proSaveSettingsBtn');busy(btn,true);status('#proSettingsStatus','Salvando configuração GameShow Pro…','busy');try{await savePatch(proSettingsPatch(),'✓ Configuração GameShow Pro salva.');}catch(e){status('#proSettingsStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
async function setOverlay(mode){status('#proRemoteStatus','Atualizando telão…','busy');try{await savePatch({pro_presentation_overlay:mode},'');status('#proRemoteStatus',mode==='none'?'✓ Conteúdo oficial restaurado.':`✓ Overlay ${mode} enviado ao telão.`,'ok');}catch(e){status('#proRemoteStatus',e.message||String(e),'error');}}

function csvParse(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'){if(quote&&n==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>String(x).trim()))rows.push(row);row=[];}else cell+=c;}row.push(cell);if(row.some(x=>String(x).trim()))rows.push(row);return rows;}
function boolish(v,def=false){const s=String(v??'').trim().toLowerCase();if(!s)return def;return['1','true','sim','yes','y','s'].includes(s);}
function normalizeImportObject(o={}){const prompt=String(o.prompt||o.pergunta||'').trim(),type=String(o.question_type||o.type||o.tipo||'choice').toLowerCase().startsWith('num')?'numeric':'choice',opts=[];if(type==='choice'){for(const k of ['A','B','C','D','E']){const val=o[k]??o[k.toLowerCase()]??o[`option_${k.toLowerCase()}`];if(String(val??'').trim())opts.push({key:k,text:String(val).trim()});}}const correctRaw=o.correct_choice??o.correct??o.correta??o.resposta??'',correctNumber=o.correct_number??o.correct??o.correta??o.resposta??null;let gameSpec=o.game_spec??o.gameSpec??{};if(typeof gameSpec==='string'&&gameSpec.trim()){try{gameSpec=JSON.parse(gameSpec);}catch{gameSpec={};}}if(!gameSpec||Array.isArray(gameSpec)||typeof gameSpec!=='object')gameSpec={};return{prompt,question_type:type,options:type==='choice'?opts:null,correct_choice:type==='choice'?String(correctRaw).trim().toUpperCase():null,correct_number:type==='numeric'?Number(String(correctNumber).replace(',','.')):null,points:Number(o.points??o.pontos??100)||100,time_limit_seconds:Number(o.time_limit_seconds??o.time??o.tempo??30)||30,category:String(o.category??o.categoria??'Geral').trim()||'Geral',difficulty:String(o.difficulty??o.dificuldade??'medio').toLowerCase(),score_enabled:boolish(o.score_enabled??o.pontuar,true),speed_bonus_pct:Number(o.speed_bonus_pct??o.bonus_velocidade??0)||0,is_tiebreaker:boolish(o.is_tiebreaker??o.desempate,false),presenter_notes:String(o.presenter_notes??o.nota??''),media_type:String(o.media_type??'none').toLowerCase(),media_url:String(o.media_url??''),media_caption:String(o.media_caption??''),special_type:String(o.special_type??'normal').toLowerCase(),tags:Array.isArray(o.tags)?o.tags:String(o.tags??'').split(/[|;]/).map(x=>x.trim()).filter(Boolean),source_label:String(o.source_label??o.fonte??''),starred:boolish(o.starred??o.favorita,false),game_type:String(o.game_type??'standard').toLowerCase(),game_spec:gameSpec};}
function validateImport(q){const errs=[];if(!q.prompt)errs.push('enunciado vazio');if(q.question_type==='choice'){if(q.options.length<4)errs.push('mínimo A-D');if(!q.options.some(o=>o.key===q.correct_choice))errs.push('gabarito inválido');}else if(!Number.isFinite(q.correct_number))errs.push('número correto inválido');if(q.media_type!=='none'&&q.media_url&&!safeUrl(q.media_url))errs.push('mídia sem HTTPS');if(!Object.hasOwn(GAME_LABELS,q.game_type))errs.push('game_type inválido');return errs;}
function analyzeImport(){const text=$('#proImportText').value.trim(),format=$('#proImportFormat').value;proImportRows=[];if(!text){renderImport();return;}try{const actual=format==='auto'?(text.startsWith('[')||text.startsWith('{')?'json':'csv'):format;if(actual==='json'){const parsed=JSON.parse(text),arr=Array.isArray(parsed)?parsed:(Array.isArray(parsed.questions)?parsed.questions:[]);proImportRows=arr.map(normalizeImportObject);}else{const rows=csvParse(text);if(rows.length<2)throw new Error('CSV sem linhas de dados.');const head=rows[0].map(x=>String(x).trim());proImportRows=rows.slice(1).map(cols=>normalizeImportObject(Object.fromEntries(head.map((h,i)=>[h,cols[i]??'']))));}renderImport();}catch(e){status('#proImportStatus',e.message||String(e),'error');$('#proRunImportBtn').disabled=true;}}
function renderImport(){const box=$('#proImportPreview');const checked=proImportRows.map((q,i)=>({q,i,errors:validateImport(q)}));const good=checked.filter(x=>!x.errors.length).length;$('#proImportBadge').textContent=`${good} válidas`;box.innerHTML=checked.slice(0,60).map(x=>`<div class="pro-import-row ${x.errors.length?'bad':'good'}"><b>${x.i+1}</b><span>${esc(x.q.prompt||'Sem enunciado')}</span><em>${x.errors.length?esc(x.errors.join(' • ')):'OK'}</em></div>`).join('');const roleDisabled=$('#proRunImportBtn').dataset.roleDisabled==='1';$('#proRunImportBtn').disabled=roleDisabled||!checked.length||good!==checked.length;status('#proImportStatus',checked.length?`${checked.length} linha(s) analisadas • ${good} válidas${good!==checked.length?` • ${checked.length-good} com erro`:''}`:'Cole um CSV/JSON ou selecione um arquivo.',good===checked.length&&good?'ok':'');}
async function runImport(){const btn=$('#proRunImportBtn');busy(btn,true);status('#proImportStatus','Importando lote…','busy');try{const errors=proImportRows.flatMap(q=>validateImport(q));if(errors.length)throw new Error('Corrija os erros antes de importar.');if($('#proImportMode').value==='replace'&&!confirm('Substituir o banco ativo pelas perguntas deste lote? O histórico das partidas permanece preservado.'))return;const{data,error}=await db.rpc('admin_import_questions_pro',{p_questions:proImportRows,p_mode:$('#proImportMode').value});if(error)throw error;status('#proImportStatus',`✓ ${Number(data?.imported||proImportRows.length)} perguntas importadas.`,'ok');await loadQuestions();}catch(e){status('#proImportStatus',e.message||String(e),'error');}finally{busy(btn,false);renderImport();}}
function csvModel(){const head=['prompt','type','A','B','C','D','E','correct','points','time','category','difficulty','media_type','media_url','media_caption','special_type','tags','source_label','starred','game_type','game_spec'];const example=['Qual é a capital do Brasil?','choice','São Paulo','Brasília','Salvador','Recife','Manaus','B','100','30','Geografia','facil','image','https://exemplo.com/brasil.jpg','Mapa ilustrativo','normal','geografia;capital','Treinamento','true','hidden_image','{"instructions":"A imagem vai sendo revelada","correct_choice":"B"}'];return head.join(',')+'\n'+example.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')+'\n';}

async function loadDashboard(){const btn=$('#proRefreshDashboardBtn');busy(btn,true);status('#proDashboardStatus','Calculando dashboard…','busy');try{if(!proRoom)throw new Error('Selecione uma sala.');const{data,error}=await db.rpc('admin_event_dashboard',{p_room_id:proRoom.id});if(error)throw error;proDashboard=data;renderDashboard();status('#proDashboardStatus',`✓ Dashboard gerado em ${new Date().toLocaleTimeString('pt-BR')}.`,'ok');}catch(e){status('#proDashboardStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
function renderDashboard(){const d=proDashboard||{},s=d.summary||{},metrics=[['JOGADORES',s.players??0],['ROUNDS',s.rounds??0],['RESPOSTAS',s.answers??0],['TEMPO MÉDIO',s.avg_response_ms?`${(Number(s.avg_response_ms)/1000).toFixed(1)}s`:'—'],['PONTOS',s.total_points??0]];$('#proDashboardSummary').innerHTML=metrics.map(([l,v])=>`<div class="pro-metric"><small>${l}</small><strong>${esc(v)}</strong></div>`).join('');const body=$('#proDashboardTable tbody'),rows=Array.isArray(d.questions)?d.questions:[];body.innerHTML=rows.map(r=>`<tr><td>${Number(r.round_no)||0}</td><td>${esc(r.prompt||'')}</td><td>${esc(r.category||'')}</td><td>${r.accuracy===null||r.accuracy===undefined?'—':`${Number(r.accuracy).toFixed(1)}%`}</td><td>${Number(r.answers)||0}</td><td>${r.avg_response_ms?`${(Number(r.avg_response_ms)/1000).toFixed(1)}s`:'—'}</td><td>${esc(r.special_type||'normal')}</td><td>${esc(GAME_LABELS[r.game_type]||r.game_type||'Padrão')}</td></tr>`).join('')||'<tr><td colspan="8">Sem rounds registrados.</td></tr>';}
function exportDashboardJson(){if(!proDashboard)return status('#proDashboardStatus','Atualize o dashboard primeiro.','error');download(`QuizRounds_dashboard_${proRoom?.code||'sala'}.json`,JSON.stringify(proDashboard,null,2),'application/json;charset=utf-8');}
function exportDashboardCsv(){if(!proDashboard)return status('#proDashboardStatus','Atualize o dashboard primeiro.','error');const head=['round','pergunta','categoria','acerto_pct','respostas','tempo_medio_ms','especial','game'],rows=(proDashboard.questions||[]).map(r=>[r.round_no,r.prompt,r.category,r.accuracy??'',r.answers,r.avg_response_ms??'',r.special_type||'normal',r.game_type||'standard']);const csv=[head,...rows].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');download(`QuizRounds_dashboard_${proRoom?.code||'sala'}.csv`,csv,'text/csv;charset=utf-8');}

async function loadPermissions(){if(!isOwner()){$('#proPermissionList').innerHTML='<div class="pro-status">Somente o proprietário pode listar e alterar outros administradores.</div>';return;}const{data,error}=await db.rpc('admin_list_role_members');if(error)throw error;const rows=Array.isArray(data)?data:[];$('#proPermissionList').innerHTML=rows.map(r=>`<div class="pro-permission-row"><span>${esc(r.email||r.user_id)}</span><b class="pro-role">${esc(r.role)}</b></div>`).join('')||'<div class="pro-status">Nenhum membro.</div>';}
async function applyPermission(){const btn=$('#proPermissionApplyBtn');busy(btn,true);status('#proPermissionStatus','Aplicando permissão…','busy');try{const email=$('#proPermissionEmail').value.trim();if(!email)throw new Error('Informe o e-mail.');const{data,error}=await db.rpc('admin_set_role_by_email',{p_email:email,p_role:$('#proPermissionSelect').value});if(error)throw error;status('#proPermissionStatus',`✓ ${data?.email||email}: ${data?.role||'atualizado'}.`,'ok');$('#proPermissionEmail').value='';await loadPermissions();}catch(e){status('#proPermissionStatus',e.message||String(e),'error');}finally{busy(btn,false);}}



const GAME_HINTS={
  standard:'Usa as alternativas/número do editor normal.',nearest:'Valor numérico: só o participante mais próximo recebe a pontuação.',precision:'Valor numérico por faixas ouro, prata e bronze.',ordering:'Digite os itens na ordem correta, um por linha.',matching:'Use “item da esquerda => item da direita”.',classification:'Use “item => categoria”.',true_false_series:'Use “V|afirmação” ou “F|afirmação”.',hidden_image:'Use uma pergunta de múltipla escolha com imagem. Ela é revelada progressivamente.',zoom_mystery:'Use uma pergunta com imagem. O zoom diminui durante o tempo.',who_am_i:'Cada linha vira uma pista revelada progressivamente.',before_after:'A mídia principal é o “antes”; informe a mídia secundária para o “depois”.',case_study:'As linhas formam o cenário técnico. A resposta usa as alternativas normais.',decision_tree:'Use “A=>consequência” para descrever o resultado de cada decisão.',team_mission:'Use “OK|tarefa correta” e “X|distrator”. Pode marcar várias.',bingo:'Um termo por linha. O sistema cria uma cartela e linhas vencedoras.',wheel:'Use “Rótulo | multiplicador”, por exemplo Bônus 2x | 2.',surprise:'Use “Prêmio | multiplicador”, por exemplo Caixa Ouro | 2.',crowd_prediction:'Os jogadores tentam escolher a alternativa que será maioria.',live_poll:'Enquete sem pontuação; use as alternativas normais.',audience_choice:'Votação entre opções; sem pontuação.',category_choice:'Escolha de categoria como round; sem pontuação.'
};
function gameLines(){return $('#proGameItems').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,80);}
function gameNumber(id,fallback=null){const raw=$(id)?.value?.trim().replace(',','.');if(!raw)return fallback;const n=Number(raw);return Number.isFinite(n)?n:fallback;}
function safeId(prefix,i){return `${prefix}${i+1}`;}
function questionOptions(q){return Array.isArray(q?.options)?q.options.map(o=>({id:String(o.key||''),text:String(o.text||'')})).filter(o=>o.id):[];}
function gameSpecFromUi(q,type){const lines=gameLines(),instructions=$('#proGameInstructions').value.trim(),reveal_text=$('#proGameReveal').value.trim(),base={instructions,reveal_text};
  if(type==='standard')return{};
  if(type==='nearest')return{...base,target:gameNumber('#proGameTarget',q?.correct_number??null)};
  if(type==='precision')return{...base,target:gameNumber('#proGameTarget',q?.correct_number??null),precision:{gold:gameNumber('#proPrecisionGold',1),silver:gameNumber('#proPrecisionSilver',5),bronze:gameNumber('#proPrecisionBronze',10)}};
  if(type==='ordering'){const items=lines.map((text,i)=>({id:safeId('i',i),text}));return{...base,items,correct_order:items.map(x=>x.id)};}
  if(type==='matching'){const left_items=[],right_items=[],correct_matches={};lines.forEach((line,i)=>{const [a,b]=line.split(/\s*=>\s*/,2),lid=safeId('l',i),rid=safeId('r',i);if(!a||!b)return;left_items.push({id:lid,text:a});right_items.push({id:rid,text:b});correct_matches[lid]=rid;});return{...base,left_items,right_items,correct_matches};}
  if(type==='classification'){const items=[],categories=[],classification_answers={},seen=new Map();lines.forEach((line,i)=>{const [a,b]=line.split(/\s*=>\s*/,2);if(!a||!b)return;const iid=safeId('i',i);items.push({id:iid,text:a});let cid=seen.get(b.toLowerCase());if(!cid){cid=safeId('c',seen.size);seen.set(b.toLowerCase(),cid);categories.push({id:cid,label:b});}classification_answers[iid]=cid;});return{...base,items,categories,classification_answers};}
  if(type==='true_false_series'){const statements=[],statement_answers=[];lines.forEach((line,i)=>{const m=line.match(/^\s*([VvFf])\s*[|:-]\s*(.+)$/);statements.push({id:safeId('s',i),text:m?m[2]:line});statement_answers.push(m?m[1].toUpperCase()==='V':true);});return{...base,statements,statement_answers};}
  if(type==='who_am_i')return{...base,clues:lines,correct_choice:q?.correct_choice||''};
  if(type==='before_after')return{...base,before_url:q?.media_url||'',after_url:safeUrl($('#proGameMedia2Url').value),correct_choice:q?.correct_choice||''};
  if(type==='case_study')return{...base,scenario:lines.join('\n'),correct_choice:q?.correct_choice||''};
  if(type==='decision_tree'){const outcomes={};lines.forEach(line=>{const [a,b]=line.split(/\s*=>\s*/,2);if(a&&b)outcomes[a.trim().toUpperCase()]=b.trim();});return{...base,outcomes,correct_choice:q?.correct_choice||''};}
  if(type==='team_mission'){const options=[],correct_choices=[];lines.forEach((line,i)=>{const m=line.match(/^\s*(OK|X|V|F)\s*[|:-]\s*(.+)$/i),id=String.fromCharCode(65+i);options.push({id,text:m?m[2]:line});if(!m||['OK','V'].includes(m[1].toUpperCase()))correct_choices.push(id);});return{...base,options,correct_choices};}
  if(type==='bingo'){const size=lines.length>=16?5:3,cells=lines.slice(0,size*size).map((text,i)=>({id:safeId('b',i),text})),winning_lines=[];for(let r=0;r<size;r++)winning_lines.push(Array.from({length:size},(_,c)=>cells[r*size+c]?.id).filter(Boolean));for(let c=0;c<size;c++)winning_lines.push(Array.from({length:size},(_,r)=>cells[r*size+c]?.id).filter(Boolean));winning_lines.push(Array.from({length:size},(_,i)=>cells[i*size+i]?.id).filter(Boolean));winning_lines.push(Array.from({length:size},(_,i)=>cells[i*size+(size-1-i)]?.id).filter(Boolean));return{...base,size,cells,winning_lines};}
  if(type==='wheel'||type==='surprise'){const key=type==='wheel'?'segments':'boxes',rows=lines.map((line,i)=>{const [label,mul]=line.split('|').map(x=>x.trim());return{id:safeId(type==='wheel'?'w':'x',i),label:label||`Opção ${i+1}`,multiplier:Number(mul)||1};});return{...base,[key]:rows,correct_choice:q?.correct_choice||''};}
  if(['hidden_image','zoom_mystery'].includes(type))return{...base,correct_choice:q?.correct_choice||'',reveal_seconds:q?.time_limit_seconds||30};
  if(['crowd_prediction','live_poll','audience_choice','category_choice'].includes(type))return{...base,options:questionOptions(q)};
  return{...base,correct_choice:q?.correct_choice||''};
}
function gameLinesFromSpec(type,spec={}){if(type==='ordering')return(spec.items||[]).map(x=>x.text).join('\n');if(type==='matching')return(spec.left_items||[]).map(x=>`${x.text} => ${(spec.right_items||[]).find(r=>r.id===spec.correct_matches?.[x.id])?.text||''}`).join('\n');if(type==='classification')return(spec.items||[]).map(x=>`${x.text} => ${(spec.categories||[]).find(c=>c.id===spec.classification_answers?.[x.id])?.label||''}`).join('\n');if(type==='true_false_series')return(spec.statements||[]).map((x,i)=>`${spec.statement_answers?.[i]===false?'F':'V'}|${x.text}`).join('\n');if(type==='who_am_i')return(spec.clues||[]).join('\n');if(type==='case_study')return String(spec.scenario||'');if(type==='decision_tree')return Object.entries(spec.outcomes||{}).map(([k,v])=>`${k}=>${v}`).join('\n');if(type==='team_mission')return(spec.options||[]).map(x=>`${(spec.correct_choices||[]).includes(x.id)?'OK':'X'}|${x.text}`).join('\n');if(type==='bingo')return(spec.cells||[]).map(x=>x.text).join('\n');if(type==='wheel')return(spec.segments||[]).map(x=>`${x.label} | ${x.multiplier||1}`).join('\n');if(type==='surprise')return(spec.boxes||[]).map(x=>`${x.label} | ${x.multiplier||1}`).join('\n');return'';}
function updateGameHint(){const type=$('#proGameType')?.value||'standard';$('#proGameBadge').textContent=(GAME_LABELS[type]||type).toUpperCase();$('#proGameHint').textContent=GAME_HINTS[type]||'Mecânica avançada.';const numeric=['nearest','precision'].includes(type);document.querySelector('#proGameTarget')?.closest('.pro-form')?.classList.toggle('game-field-highlight',numeric);}
function loadGameFields(q){const type=q?.game_type||'standard',spec=q?.game_spec||{};$('#proGameType').value=Object.hasOwn(GAME_LABELS,type)?type:'standard';$('#proGameInstructions').value=spec.instructions||'';$('#proGameTarget').value=spec.target??q?.correct_number??'';$('#proPrecisionGold').value=spec.precision?.gold??'';$('#proPrecisionSilver').value=spec.precision?.silver??'';$('#proPrecisionBronze').value=spec.precision?.bronze??'';$('#proGameMedia2Url').value=spec.after_url||'';$('#proGameItems').value=gameLinesFromSpec(type,spec);$('#proGameReveal').value=spec.reveal_text||'';updateGameHint();}
function fillGameTemplate(){const type=$('#proGameType').value;if(type==='ordering')$('#proGameItems').value='Preparar equipamento\nConferir conexões\nExecutar procedimento\nRegistrar resultado';else if(type==='matching')$('#proGameItems').value='Osciloscópio => Aquisição de sinal\nBomba => Controle de pressão\nRelé => Chaveamento\nSensor => Medição';else if(type==='classification')$('#proGameItems').value='Óculos de proteção => EPI\nOsciloscópio => Equipamento\nLuva => EPI\nAmostra padrão => Material';else if(type==='true_false_series')$('#proGameItems').value='V|O EPI deve ser verificado antes do ensaio\nF|É permitido ignorar o checklist\nV|A calibração deve ser rastreável';else if(type==='who_am_i')$('#proGameItems').value='Sou usado para visualizar sinais\nTenho canais de aquisição\nPosso medir tempo e amplitude';else if(type==='decision_tree')$('#proGameItems').value='A=>Procedimento segue normalmente\nB=>Interromper e verificar segurança\nC=>Solicitar apoio técnico\nD=>Revisar a preparação';else if(type==='team_mission')$('#proGameItems').value='OK|Conferir EPI\nOK|Validar conexões\nX|Ignorar alarme\nOK|Registrar dados';else if(type==='bingo')$('#proGameItems').value='Segurança\nCalibração\nPressão\nTemperatura\nAmostra\nSensor\nAquisição\nProcedimento\nChecklist';else if(type==='wheel')$('#proGameItems').value='Pontuação normal | 1\nBônus 2x | 2\nBônus 1,5x | 1.5\nSem multiplicador | 1';else if(type==='surprise')$('#proGameItems').value='Caixa Azul | 1\nCaixa Ouro | 2\nCaixa Verde | 1.5\nCaixa Prata | 1';else if(type==='case_study')$('#proGameItems').value='Durante o ensaio, a pressão oscila acima do esperado. O operador confirma as conexões e verifica o sistema antes de prosseguir.';else status('#proGameSpecStatus','Este game usa as alternativas e/ou mídia da pergunta normal.','ok');updateGameHint();}
function clearGame(){['#proGameInstructions','#proGameTarget','#proPrecisionGold','#proPrecisionSilver','#proPrecisionBronze','#proGameMedia2Url','#proGameItems','#proGameReveal'].forEach(id=>{if($(id))$(id).value='';});$('#proGameType').value='standard';updateGameHint();}
function refreshSmartCategories(){const sel=$('#proSmartCategory');if(!sel)return;const keep=sel.value,cats=[...new Set(proQuestions.map(q=>String(q.category||'Geral').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));sel.innerHTML='<option value="">Selecione…</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(cats.includes(keep))sel.value=keep;}
async function saveAutomation(){const btn=$('#proSaveAutomationBtn');busy(btn,true);status('#proAutomationStatus','Salvando…','busy');try{await savePatch({pro_exam_mode:$('#proExamMode').checked,pro_progressive_mode:$('#proProgressiveMode').checked},'');status('#proAutomationStatus','✓ Automação salva.','ok');}catch(e){status('#proAutomationStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
async function queueSmart(strategy){const btn=strategy==='chosen'?$('#proQueueChosenBtn'):strategy==='random'?$('#proQueueRandomBtn'):strategy==='progressive'?$('#proQueueProgressiveBtn'):$('#proQueueAudienceBtn');busy(btn,true);status('#proSmartQueueStatus','Escolhendo pergunta…','busy');try{if(!proRoom)throw new Error('Crie ou retome uma sala.');const value=strategy==='chosen'?$('#proSmartCategory').value:null;if(strategy==='chosen'&&!value)throw new Error('Escolha uma categoria.');const{data,error}=await db.rpc('admin_queue_smart_question',{p_room_id:proRoom.id,p_strategy:strategy,p_value:value});if(error)throw error;status('#proSmartQueueStatus',`✓ Enfileirada: ${data?.category||'—'} / ${data?.difficulty||'—'} — ${data?.prompt||''}`,'ok');window.dispatchEvent(new CustomEvent('quiz2:queue-updated'));}catch(e){status('#proSmartQueueStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
function voteOptionsFromUi(){return $('#proPublicVoteOptions').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,12).map(x=>({value:x,label:x}));}
async function setPublicVote(open){const btn=open?$('#proOpenPublicVoteBtn'):$('#proClosePublicVoteBtn');busy(btn,true);status('#proPublicVoteStatus',open?'Abrindo votação…':'Fechando votação…','busy');try{if(!proRoom)throw new Error('Crie uma sala.');const existing=settings().pro_public_vote||{},payload={open,type:'audience_choice',question:$('#proPublicVoteQuestion').value.trim()||'Escolha do público',options:voteOptionsFromUi()};if(!open){payload.question=existing.question||payload.question;payload.options=Array.isArray(existing.options)?existing.options:payload.options;}if(open&&payload.options.length<2)throw new Error('Informe pelo menos duas opções.');const{data,error}=await db.rpc('admin_set_public_vote',{p_room_id:proRoom.id,p_payload:payload});if(error)throw error;proRoom.settings={...settings(),pro_public_vote:data};status('#proPublicVoteStatus',open?'✓ Votação aberta nos celulares.':'✓ Votação fechada.','ok');await loadPublicVoteSummary();}catch(e){status('#proPublicVoteStatus',e.message||String(e),'error');}finally{busy(btn,false);}}
async function loadPublicVoteSummary(){const box=$('#proPublicVotePreview');if(!box||!proRoom){if(box)box.innerHTML='';return;}try{const{data,error}=await db.rpc('pro_public_vote_summary',{p_code:proRoom.code});if(error)throw error;const vote=data?.vote||{},rows=Array.isArray(data?.results)?data.results:[],total=rows.reduce((s,r)=>s+Number(r.count||0),0);$('#proPublicVoteQuestion').value=vote.question||$('#proPublicVoteQuestion').value;$('#proPublicVoteOptions').value=Array.isArray(vote.options)?vote.options.map(x=>x.label||x.value).join('\n'):$('#proPublicVoteOptions').value;box.innerHTML=rows.length?rows.map(r=>`<div class="pro-vote-row"><strong>${esc(r.value)}</strong><span><i style="width:${total?Math.round(Number(r.count||0)*100/total):0}%"></i></span><b>${Number(r.count)||0}</b></div>`).join(''):'<div class="pro-status">Sem votos ainda.</div>';box.dataset.open=vote.open?'1':'0';}catch(e){box.innerHTML=`<div class="pro-status error">${esc(e.message||String(e))}</div>`;}}
function fillAutomationFromRoom(){const s=settings();if($('#proExamMode'))$('#proExamMode').checked=!!s.pro_exam_mode;if($('#proProgressiveMode'))$('#proProgressiveMode').checked=!!s.pro_progressive_mode;const v=s.pro_public_vote||{};if($('#proPublicVoteQuestion')&&v.question)$('#proPublicVoteQuestion').value=v.question;if($('#proPublicVoteOptions')&&Array.isArray(v.options))$('#proPublicVoteOptions').value=v.options.map(x=>x.label||x.value).join('\n');}
function bindGamePack(){
  $('#proGameType')?.addEventListener('change',updateGameHint);$('#proGameTemplateBtn')?.addEventListener('click',fillGameTemplate);$('#proGameClearBtn')?.addEventListener('click',clearGame);
  $('#proSaveAutomationBtn')?.addEventListener('click',saveAutomation);$('#proQueueChosenBtn')?.addEventListener('click',()=>queueSmart('chosen'));$('#proQueueRandomBtn')?.addEventListener('click',()=>queueSmart('random'));$('#proQueueProgressiveBtn')?.addEventListener('click',()=>queueSmart('progressive'));$('#proQueueAudienceBtn')?.addEventListener('click',()=>queueSmart('audience'));
  $('#proOpenPublicVoteBtn')?.addEventListener('click',()=>setPublicVote(true));$('#proClosePublicVoteBtn')?.addEventListener('click',()=>setPublicVote(false));
}

function injectRemoteProControls(){const view=$('#remoteControlView');if(!view||$('#proRemoteMobileCard'))return;const danger=view.querySelector('.remote-danger-zone');const sec=document.createElement('section');sec.id='proRemoteMobileCard';sec.className='remote-reveal-card';sec.innerHTML='<div><span class="eyebrow">TELÃO PRO</span><strong>Overlay de apresentação</strong></div><div class="remote-reveal-actions"><button data-pro-overlay="none" type="button">Conteúdo</button><button data-pro-overlay="standby" type="button">Espera</button><button data-pro-overlay="brand" type="button">Branding</button><button data-pro-overlay="sponsor" type="button">Sponsor</button></div>';(danger?.parentNode||view).insertBefore(sec,danger||null);sec.querySelectorAll('[data-pro-overlay]').forEach(b=>b.addEventListener('click',()=>setOverlay(b.dataset.proOverlay)));}


async function refreshPro(){try{status('#proSettingsStatus','Sincronizando…','busy');await verifyBackend();await loadRole();await loadRoom();await Promise.allSettled([loadTeams(),loadQuestions(),loadPermissions()]);refreshSmartCategories();fillAutomationFromRoom();await loadPublicVoteSummary();status('#proSettingsStatus',proRoom?'GameShow Pro pronto.':'Crie uma sala para ativar os recursos da partida.','ok');}catch(e){status('#proSettingsStatus',e.message||String(e),'error');}}

function bind(){
  injectRemoteProControls();bindGamePack();initProPanes();
  $$('[name="proGameMode"]').forEach(r=>r.addEventListener('change',()=>setModeActive(r.value)));$$('[name="proTeamJoinMode"]').forEach(r=>r.addEventListener('change',()=>changeTeamJoinMode(r.value)));$$('[data-pro-template]').forEach(b=>b.addEventListener('click',()=>applyProTemplate(b.dataset.proTemplate)));$('#proRoomNextDynamicsBtn')?.addEventListener('click',()=>$('#proGameModeCard')?.scrollIntoView({behavior:'smooth',block:'center'}));$('#proGenerateTeamsBtn')?.addEventListener('click',()=>generateDefaultTeams($('#proTeamCount')?.value));$('#proRefreshAssignmentsBtn')?.addEventListener('click',()=>loadTeamLobbyState());$('#proCreateRoomBtn')?.addEventListener('click',createProRoom);$('#proSaveQuickRulesBtn')?.addEventListener('click',saveQuickRules);$('#proTeamsNextBtn')?.addEventListener('click',()=>setProPane('rules'));$('#proRulesBackBtn')?.addEventListener('click',()=>setProPane(proDraftMode==='teams'?'teams':'questions'));$('#proRulesNextBtn')?.addEventListener('click',()=>setProPane('rounds'));$('#proRoundsBackBtn')?.addEventListener('click',()=>setProPane('rules'));$('#proRoundsNextReviewBtn')?.addEventListener('click',()=>setProPane('review'));$('#proRoundsNextReviewBtnBottom')?.addEventListener('click',()=>setProPane('review'));$('#proReviewBackBtn')?.addEventListener('click',()=>setProPane('rounds'));$('#proTestGameBtn')?.addEventListener('click',()=>window.quiz2AdminBridge?.testGame?.());$('#proSaveTemplateBtn')?.addEventListener('click',()=>window.quiz2AdminBridge?.saveTemplate?.());$('#proOpenQuestionBankBtn')?.addEventListener('click',openQuestionBank);$('#proOpenOfficialQueueBtn')?.addEventListener('click',openOfficialQueue);$('#proGoPresentationBtn')?.addEventListener('click',openPresentation);
  $('#proApplyModeBtn').addEventListener('click',applyMode);$('#proAddTeamBtn').addEventListener('click',()=>{if($('#proTeamList').children.length>=12)return;$('#proTeamList').append(teamRow({},$('#proTeamList').children.length));renderTeamPreview();});$('#proSaveTeamsBtn').addEventListener('click',saveTeams);$('#proRefreshTeamsBtn').addEventListener('click',()=>loadTeams().catch(e=>status('#proTeamsStatus',e.message,'error')));
  $('#proQuestionSelect').addEventListener('change',loadQuestionFields);['#proMediaType','#proMediaUrl','#proMediaCaption'].forEach(id=>$(id).addEventListener('input',renderMediaPreview));$('#proSaveQuestionBtn').addEventListener('click',saveQuestionPro);$('#proOpenQuestionEditorBtn').addEventListener('click',()=>{$('#adminTabQuestions')?.click();setTimeout(()=>document.querySelector('[data-question-pane="edit"]')?.click(),100);});
  ['#proBrandSubtitle','#proSponsorName','#proBrandFooter'].forEach(id=>$(id).addEventListener('input',refreshBrandPreview));$('#proSaveSettingsBtn').addEventListener('click',saveProSettings);$$('[data-pro-overlay]').forEach(b=>b.addEventListener('click',()=>setOverlay(b.dataset.proOverlay)));
  $('#proImportFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;$('#proImportText').value=await f.text();$('#proImportFormat').value=f.name.toLowerCase().endsWith('.json')?'json':'csv';analyzeImport();e.target.value='';});$('#proAnalyzeImportBtn').addEventListener('click',analyzeImport);$('#proRunImportBtn').addEventListener('click',runImport);$('#proDownloadCsvModelBtn').addEventListener('click',()=>download('QuizRounds_modelo_profissional_r88.csv',csvModel(),'text/csv;charset=utf-8'));
  $('#proRefreshDashboardBtn').addEventListener('click',loadDashboard);$('#proExportDashboardJsonBtn').addEventListener('click',exportDashboardJson);$('#proExportDashboardCsvBtn').addEventListener('click',exportDashboardCsv);$('#proPermissionApplyBtn').addEventListener('click',applyPermission);
  const tab=$('#adminTabPro');tab?.addEventListener('click',()=>setTimeout(refreshPro,80));window.addEventListener('storage',e=>{if(e.key==='quiz2AdminRoomId')refreshPro();});window.addEventListener('quiz2:room-changed',()=>refreshPro());
}

window.quiz2ProBridge={...(window.quiz2ProBridge||{}),setPane:(name,opts={})=>setProPane(name,opts),getPane:()=>$('#adminPanelPro')?.dataset.proPane||'room',nextFromQuestions:()=>nextFromQuestions(),renderReview:()=>renderProReview(),getMode:()=>proDraftMode};

window.addEventListener('load',()=>{bind();renderTeams();syncTeamFormationFromRoom();renderTeamAssignmentBoard();updateGameHint();setTimeout(refreshPro,900);setInterval(()=>{if(!$('#adminPanelPro')?.classList.contains('active'))return;loadPublicVoteSummary();if(proRoom&&(settings().game_mode||proDraftMode)==='teams')loadTeamLobbyState();},3500);});
